(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = { steps: [] };
  try {
    // ① 演示账号一键登录
    const res = await fetch('/api/auth/demo', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const data = await res.json();
    out.demoOk = res.ok;
    if (data.token) localStorage.setItem('token', data.token);
    if (data.user) localStorage.setItem('user', JSON.stringify(data.user));
    out.hasToken = !!localStorage.getItem('token');
    out.hasUser = !!localStorage.getItem('user');

    // ② 顶栏入口
    out.nav = [...document.querySelectorAll('header a')].map((a) => a.textContent.trim());

    // ③ 客户端跳转到项目列表（点导航，不整页刷新）
    [...document.querySelectorAll('header a')].find((a) => a.textContent.trim() === '项目')?.click();
    await sleep(3500);
    out.onProjects = location.pathname;
    out.projectsTitle = document.querySelector('.pjx-title')?.textContent || null;

    // ④ 新建卍解项目
    [...document.querySelectorAll('button')].find((b) => b.textContent.includes('新建项目'))?.click();
    await sleep(900);
    out.diffOptions = [...document.querySelectorAll('.pjx-diff-opt')].map((b) => b.textContent.trim());
    const nameInput = document.querySelector('.pjx-create input');
    out.hasNameInput = !!nameInput;
    if (!nameInput) return JSON.stringify(out);
    setV(nameInput, '服务器版测试·卍解');
    [...document.querySelectorAll('.pjx-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
    await sleep(300);
    out.picked = document.querySelector('.pjx-diff-opt-on')?.textContent.trim() || null;
    [...document.querySelectorAll('button')].find((b) => b.textContent.trim() === '创建')?.click();
    for (let i = 0; i < 16; i++) { await sleep(500); if (location.pathname.startsWith('/projects/') && document.querySelector('.pj-title')) break; }
    out.afterCreate = location.pathname;
    out.workTitle = document.querySelector('.pj-title')?.textContent || null;
    out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;
    out.codePanel = !!document.querySelector('.pc-wrap');
    out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
